import csv
import json
from datetime import datetime

BASE = "/app/data"

departments = {}
with open(BASE + "/departments.csv", newline="") as f:
    for row in csv.DictReader(f):
        departments[row["id"]] = {
            "id": row["id"],
            "name": row["name"],
            "budget": float(row["budget"]),
            "employees": [],
            "projects": []
        }

with open(BASE + "/employees.csv", newline="") as f:
    for row in csv.DictReader(f):
        emp = {
            "id": row["id"],
