averageYearsOfService = round(sum(all_years) / len(all_years), 2)

output = {
    "metadata": {
        "version": "1.0",
        "timestamp": datetime.now().isoformat(),
        "generator": "CSV-to-JSON Processor"
    },
    "organization": {
        "name": "Acme Corporation",
        "founded": "2000-01-01",
